import "io" for File, Stat

File.create("stat_a.temp") {|f| f.writeBytes("a") }
File.create("stat_b.temp") {|f| f.writeBytes("b") }
var a = Stat.path("stat_a.temp")
var b = Stat.path("stat_b.temp")
System.print(a.inode != b.inode) // expect: true
File.delete("stat_a.temp")
File.delete("stat_b.temp")
